def solve(rows):
    kept_rows = []
    state = 0
    for i, row in enumerate(rows):
        weight = 0
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and row.startswith("|") and row.endswith("|"):
            try:
                weight = int(row[1:-1])
            except ValueError:
                weight = 0
        elif isinstance(row, list):
            for item in row:
                if isinstance(item, int):
                    weight += item
                elif isinstance(item, str):
                    weight += len(item)

        if (state + weight + i) % 7 != 5 or i == len(rows) - 1:
            kept_rows.append(row)

        if weight == 0:
            state = 0
        else:
            state = (5 * state + weight) % 7

    if not kept_rows:
        return []

    final_state = state
    kept_length = len(kept_rows)
    rotation_amount = final_state % kept_length

    rotated_rows = kept_rows[rotation_amount:] + kept_rows[:rotation_amount]

    groups = {}
    for row in rotated_rows:
        if len(row) == 4 and isinstance(row, list):
            group, score, timestamp, name = row
            if group not in groups:
                groups[group] = []
            groups[group].append((score, timestamp, name))

    result = []
    for group in sorted(groups.keys()):
        best_row = None
        best_score = float('-inf')
        best_timestamp = float('inf')
        best_name = ''

        for score, timestamp, name in groups[group]:
            if score > best_score:
                best_score = score
                best_timestamp = timestamp
                best_name = name
            elif score == best_score and timestamp < best_timestamp:
                best_timestamp = timestamp
                best_name = name
            elif score == best_score and timestamp == best_timestamp and name > best_name:
                best_name = name

        result.append([group, best_name])

    return result

